	//获取源变量
	_getData = () => {
		try {
			data = JSON.parse(source.getVariable());
		} catch (err) {
			data = {};
		}
		return data
 	}
 	//保存源变量 _setData(data)
 _setData = (obj) => {
 	if(typeof obj == "object"){
 		source.setVariable(JSON.stringify(obj));
 	}
 }
 _getData();

 //获取搜索地址
 _getUrl = () => {
 	//通过js文件获取所搜地址
