.comic-contain@.comic-contain__item@data-src@js:
java.log(result);
headers={"headers":{"Referer":baseUrl}};
result.split("\n").map(imgUrl=>{

          // 提取域名并替换
          const match = imgUrl.match(/^(https?:\/\/)?([^/\s:]+)(:\d+)?(\/[a-z]comic\/.*)/);
         if (match) {
            const domain = match[2];
            imgUrl = `${match[1]}${domain}${match[4]}`;
}
return '<img src=\"'+imgUrl+','+JSON.stringify(headers)+'\">'
}).join("\n")

ruleToc.chapterUrl:
tag.a@href<js>
const queryString = `${result}`.split('?')[1]; // 获取 ? 后面的查询部分
  const params = {};
  const pairs = queryString.split('&'); // 按 & 分割键值对
  pairs.forEach(pair => {
    const [key, value] = pair.split('='); // 按 = 分割键和值
    if (key) {
      params[key] = value ? decodeURIComponent(value) : ''; // 解码特殊字符（若有）
    }
  });

let chapterUrl = `https://appcn.baozimh.com/baozimhapp/comic/chapter/${params .comic_id}/${params .section_slot}_${params .chapter_slot}.html`
chapterUrl
</js>

