ruleContent.content:
@js:
(function () {
  try {
    java.log('[STEP 1] result len=' + (result ? result.length : 'null'));

    var m = result.match(/params\s*=\s*'([^']+)'/);
    if (!m) return '<div class="error">未找到 params</div>';
    java.log('[STEP 2] match ok len=' + m[1].length);

    var buf = java.base64DecodeToByteArray(m[1]);
    java.log('[STEP 3] buf=' + buf.length);

    // ✅ 用 Packages.java.* 访问真实 JDK
    var Arrays = Packages.java.util.Arrays;
    var iv = Arrays.copyOfRange(buf, 0, 16);
    var ct = Arrays.copyOfRange(buf, 16, buf.length);
    java.log('[STEP 4] iv=' + iv.length + ' ct=' + ct.length);

    var key = java.hexDecodeToByteArray('355626526f52254a6640704a50796446');

    // 方案A：继续用 legado 封装（最稳）
    var c = java.createSymmetricCrypto('AES/CBC/PKCS5Padding', key, iv);
    var plainBytes = c.decrypt(ct);   // 若报错再试 c.doFinal(ct)
    java.log('[STEP 5] decrypt ok');

    var jsonStr = java.bytesToStr(plainBytes, 'UTF-8');
    java.log('[STEP 6] ' + jsonStr.substring(0, 200));

    var d = JSON.parse(jsonStr);
    var host = (d.images_domain || (d.images_hosts && d.images_hosts[0]) || d.cdnurl || '').replace(/\/+$/, '');
    var imgs = d.chapter_images || [];
    var out = '';
    for (var i = 0; i < imgs.length; i++) {
      var t = imgs[i];
      if (/^(https?:|\/\/)/i.test(t)) {
        out += '<img src="' + t + '">\n';
      } else {
        var p = t.replace(/^\/+/, '');
        if (d.images_base64) p = java.base64Encode(p, 2);
        out += '<img src="' + host + '/' + p + '">\n';
      }
    }
    return out.trim();

  } catch (e) {
    java.log('[FATAL] ' + e + (e.stack ? '\n' + e.stack : ''));
    return '<div class="error">' + e + '</div>';
  }
})();

